// Function to get the MAC address
function getMacAddress(): string {
  const interfaces = networkInterfaces();
  for (const name of Object.keys(interfaces)) {
    for (const iface of interfaces[name] || []) {
      if (!iface.internal && iface.mac) {
        return iface.mac; // Return the MAC address of the first external interface
      }
    }
  }
  throw new Error("Unable to retrieve MAC address.");
}

// Derive a 32-byte key from the MAC address
function deriveEncryptionKey(macAddress: string): Buffer {
  return crypto.createHash("sha256").update(macAddress).digest();
}
ipcMain.handle(
  "SAVE_MESSAGE",
  async (event, userId: string, message: MessageLocal) => {
    const userDir = path.join(
      app.getPath("userData"),
      "messages",
      `${message.conversationId}-${userId}`,
    );
    if (!fs.existsSync(userDir)) {
      fs.mkdirSync(userDir, { recursive: true });
    }
    console.log("Messages directory:", userDir);
    console.log("Current file:", __filename);
    const messagesFile = path.join(
      userDir,
      `${message.conversationId}-${userId}.json`,
    );
    let messages = [];

    // Get MAC address and derive encryption key
    const macAddress = getMacAddress();
    const ENCRYPTION_KEY = deriveEncryptionKey(macAddress);
    const IV_LENGTH = 12; // Recommended IV length for GCM is 12 bytes

    // Encrypt message content
    const iv = crypto.randomBytes(IV_LENGTH);
    const cipher = crypto.createCipheriv("aes-256-gcm", ENCRYPTION_KEY, iv);

    let encryptedContent = cipher.update(message.content, "utf8");
    encryptedContent = Buffer.concat([encryptedContent, cipher.final()]);
    const authTag = cipher.getAuthTag();

    // Add encrypted content, IV, and auth tag to message
    if (fs.existsSync(messagesFile)) {
      const data = fs.readFileSync(messagesFile, "utf8");
      messages = JSON.parse(data);
    }

    const encryptedMessage = {
      ...message,
      _id: messages.length + 1,
      content: encryptedContent.toString("hex"),
      iv: iv.toString("hex"),
      authTag: authTag.toString("hex"),
    };

    messages.push(encryptedMessage);
    fs.writeFileSync(messagesFile, JSON.stringify(messages));
    return true;
  },
);

ipcMain.handle(
  "GET_MESSAGES",
  async (event, userId: string, conversationId: string) => {
    const messagesFile = path.join(
      app.getPath("userData"),
      "messages",
      `${conversationId}-${userId}`,
      `${conversationId}-${userId}.json`,
    );

    if (!fs.existsSync(messagesFile)) {
      return [];
    }
    const data: MessageLocal[] = JSON.parse(
      fs.readFileSync(messagesFile, "utf8"),
    );
    // Get MAC address and derive encryption key for decryption
    const macAddress = getMacAddress();
    const ENCRYPTION_KEY = deriveEncryptionKey(macAddress);

    // Decrypt each message
    const decryptedData = data.map((message) => {
      if (message.type === "file") {
        return message;
      } else {
        // Convert hex strings back to buffers
        const iv = Buffer.from(message.iv, "hex");
        const authTag = Buffer.from(message.authTag, "hex");
        const encryptedContent = Buffer.from(message.content, "hex");

        // Create decipher
        const decipher = crypto.createDecipheriv(
          "aes-256-gcm",
          ENCRYPTION_KEY,
          iv,
        );
        decipher.setAuthTag(authTag);

        // Decrypt
        let decryptedContent = decipher.update(encryptedContent);
        decryptedContent = Buffer.concat([decryptedContent, decipher.final()]);

        // Return message with decrypted content
        return {
          ...message,
          content: decryptedContent.toString("utf8"),
        };
      }
    });
    return decryptedData;
  },
);

