ipcMain.handle("GET_FILE", async (event, filePath: string) => {
  if (!fs.existsSync(filePath)) {
    throw new Error("File not found");
  }
  return fs.readFileSync(filePath);
});

ipcMain.handle("GET_USER_FILES", async (event, userId: string) => {
  const userDir = path.join(app.getPath("userData"), "files", userId);
  if (!fs.existsSync(userDir)) {
    return [];
  }
  return fs.readdirSync(userDir);
});

